mapper.sql:
WHERE q.bank_id=#{scope.questionBankId} AND q.status='ACTIVE'
    AND q.id IN #{id}
    AND q.chapter_id IN #{id}
    AND EXISTS(SELECT 1 FROM user_favorite f WHERE f.user_id=#{userId} AND f.question_id=q.id)
    AND (SELECT coalesce(i.self_assessment,i.outcome) FROM practice_item i JOIN practice_session ps ON ps.id=i.session_id WHERE i.question_id=q.id AND ps.user_id=#{userId} AND ps.status='SUBMITTED' AND (i.outcome IN ('CORRECT','WRONG') OR i.self_assessment IS NOT NULL) ORDER BY ps.submitted_at DESC,ps.id DESC LIMIT 1)='WRONG'
